function DemoStory({ onClose }: { onClose: () => void }) {
  const steps = ["Citizen report submitted", "Evidence consistency checked", "Similar reports clustered", "Community evidence increased", "Incident prioritized", "Authority acknowledged", "Inspection team assigned", "Work marked in progress", "Citizen verification requested"];
  const [step, setStep] = useState(0);
  useEffect(() => { const timer = window.setInterval(() => setStep((current) => current >= steps.length - 1 ? current : current + 1), 1100); return () => window.clearInterval(timer); }, [steps.length]);
  const done = step === steps.length - 1;
  return <div className="fixed inset-0 z-[60] grid place-items-center bg-ink/70 p-4 backdrop-blur-sm"><div className="w-full max-w-[510px] overflow-hidden rounded-[28px] bg-paper shadow-2xl"><div className="relative bg-ink px-7 pb-8 pt-7 text-white"><button onClick={onClose} className="absolute right-5 top-5 text-white/50 hover:text-white"><X size={18} /></button><div className="mb-7 flex items-center gap-3"><span className="grid h-11 w-11 place-items-center rounded-[14px] bg-teal text-ink"><Sparkles size={20} /></span><div><div className="font-display text-lg font-bold">3-minute demo</div><div className="text-xs text-white/55">From observation to accountable response</div></div></div><div className="mb-3 flex items-end justify-between"><span className="text-[10px] font-bold uppercase tracking-[.18em] text-teal">Live storyline</span><span className="font-display text-2xl font-bold">{String(step + 1).padStart(2, "0")}<span className="text-white/25"> / {String(steps.length).padStart(2, "0")}</span></span></div><div className="h-1.5 overflow-hidden rounded-full bg-white/10"><div className="h-full rounded-full bg-teal transition-all duration-500" style={{ width: `${((step + 1) / steps.length) * 100}%` }} /></div></div><div className="space-y-1 px-7 py-6">{steps.map((item, index) => <div key={item} className={`flex items-center gap-3 rounded-xl px-3 py-2.5 transition-all ${index === step ? "bg-teal/10 text-ink" : index < step ? "text-ink/45" : "text-ink/25"}`}><span className={`grid h-6 w-6 shrink-0 place-items-center rounded-full text-[10px] font-bold ${index < step ? "bg-teal text-ink" : index === step ? "border-2 border-teal text-teal" : "border border-ink/10"}`}>{index < step ? <Check size={13} /> : index + 1}</span><span className={`text-sm ${index === step ? "font-bold" : ""}`}>{item}</span>{index === step && <span className="ml-auto h-2 w-2 animate-pulse rounded-full bg-teal" />}</div>)}<div className="mt-5 rounded-[15px] border border-amber/20 bg-amber/8 p-3 text-xs leading-relaxed text-ink/60"><Info size={14} className="mr-2 inline text-amber" /> Demo data is fictional and designed to show the complete FlowShield response loop.</div><div className="mt-5 flex gap-2">{done ? <Button className="flex-1" onClick={onClose}>Explore the dashboard <ArrowRight size={15} /></Button> : <Button variant="ghost" className="flex-1" onClick={onClose}>Skip demo</Button>}</div></div></div></div>;
}

const flowSteps: Array<[string, string, string, React.ElementType]> = [["01", "Report", "Location, image and lived experience — captured in under a minute.", MapPin], ["02", "Verify", "Consistency checks surface duplicates and signals that need a human look.", FileCheck2], ["03", "Understand", "Community observations reveal whether a problem is truly recurring.", Users], ["04", "Prioritize", "A transparent score makes urgency legible, never magical.", Gauge], ["05", "Respond", "Authorities acknowledge, assign, investigate and resolve.", Radio], ["06", "Verify resolution", "The person who reported it gets the final say on what changed.", CheckCircle2]];

